                base = main_screen(opts)
                # For fidelity, showing the popup text alone is enough for captures.
                sys.stdout.write(popup_text())
            else:
                sys.stdout.write(main_screen(opts, msg))
            sys.stdout.flush()
            k = read_key(0.5)
            if not k:
                continue
            if k in ('q','Q','\x03'):
