def parse_args(argv):
    opts = Opts()
    opts.prog = os.path.basename(argv[0]) or 'executable'
    args = argv[1:]
    i = 0
    while i < len(args):
        a = args[i]
        # The real CLI treats 'help' anywhere as a help request.
        if a == 'help':
            opts.flags['help'] = True
            i += 1
            continue
        if a.startswith('-') and a != '-':
            raw = a.lstrip('-')
            name, eq, val = raw.partition('=')
            # --help=false is not accepted by the original, but most bools accept =false.
            if name in BOOL_FLAGS and not eq:
                opts.flags[BOOL_FLAGS[name]] = True
                i += 1
                continue
            if name in BOOL_FLAGS and eq and name != 'help' and name != 'h':
                opts.flags[BOOL_FLAGS[name]] = (val.lower() not in ('false','0','no'))
                i += 1
                continue
            if name in VALUE_FLAGS:
                key = VALUE_FLAGS[name]
                if eq:
                    opts.values[key] = val
                    i += 1
                    continue
                if i+1 >= len(args):
                    opts.parse_error = f"Expected a following arg for flag {name}, but it did not exist."
                    return opts
                opts.values[key] = args[i+1]
                i += 2
                continue
            # Unknown flags: if no following arg, parser complains about missing arg; otherwise unknown arguments.
            if eq:
                opts.parse_error = "Unknown arguments supplied:  " + raw
                return opts
            if i+1 >= len(args):
                opts.parse_error = f"Expected a following arg for flag {name}, but it did not exist."
                return opts
            bad = [name, args[i+1].lstrip('-')]
            opts.parse_error = "Unknown arguments supplied:  " + ' '.join(bad)
            return opts
        else:
            opts.positionals.append(a)
            if len(opts.positionals) > 1:
                opts.parse_error = f"Unexpected argument: {a}"
                return opts
            i += 1
    return opts

