    return f"commit={COMMIT}, build date={BUILD_DATE}, build source=unknown, version={VERSION}, os={osname}, arch={arch}, git version={git_version()}\n"

def validate_paths(opts):
    p = opts.values.get('path')
    if p is not None:
        # --path only accepts the repository root with a .git directory/file.
        if not os.path.isdir(p) or not os.path.exists(os.path.join(p, '.git')):
            eprint_log(f"{p} is not a valid git repository.")
            return False
        try:
            os.chdir(p)
        except Exception as e:
            eprint_log(f"Failed to change directory to {p}: {e}")
            return False
    wt = opts.values.get('work-tree')
    if wt is not None:
        try:
            os.chdir(wt)
        except FileNotFoundError:
            eprint_log(f"Failed to change directory to {wt}: chdir {wt}: no such file or directory")
            return False
        except Exception as e:
            eprint_log(f"Failed to change directory to {wt}: {e}")
            return False
    return True

def tail_logs(opts):
