    sys.stdout.flush()
    if not os.path.exists(lf):
        eprint_log("Log file does not exist. Run `lazygit --debug` first to create the log file")
        return 1
    try:
        with open(lf, 'r') as f:
            sys.stdout.write(f.read())
            sys.stdout.flush()
            # behave like tail -f until interrupted
            while True:
                line = f.readline()
                if line:
                    sys.stdout.write(line); sys.stdout.flush()
                else:
