def read_simple_config(opts):
    result = {}
    paths = []
    ucf = opts.values.get('use-config-file')
    if ucf:
        paths.extend([p for p in ucf.split(',') if p])
    else:
        paths.append(os.path.join(config_dir(opts), 'config.yml'))
