    try:
        gd = subprocess.check_output(['git','rev-parse','--git-dir'], text=True, stderr=subprocess.DEVNULL).strip()
        if gd:
            paths.append(os.path.join(gd, 'lazygit.yml'))
    except Exception:
        pass
    for p in paths:
        try:
            for line in open(p, 'r', errors='ignore'):
                s = line.strip()
                if not s or s.startswith('#') or ':' not in s: continue
                k, v = s.split(':', 1)
                k = k.strip(); v = v.strip().strip('"\'')
