def draw_box(title, lines, width, height, active=False, footer=None):
    title = title[:max(0,width-4)]
    top = '╭─' + title + '─' * max(0, width - len(title) - 3) + '╮'
    bot_text = footer or ''
    if bot_text:
        bot = '╰' + '─' * max(0, width-len(bot_text)-2) + bot_text[:width-2] + '─╯'
        bot = bot[:width-1] + '╯' if len(bot) != width else bot
    else:
        bot = '╰' + '─'*(width-2) + '╯'
    out = [top[:width]]
    for i in range(height-2):
        text = lines[i] if i < len(lines) else ''
        text = text.replace('\t','    ')
        out.append('│' + text[:width-2].ljust(width-2) + '│')
    out.append(bot[:width])
    return out

def merge_lr(left, right):
    h = max(len(left), len(right))
    lw = max((len(x) for x in left), default=0)
    res=[]
    for i in range(h):
        l = left[i] if i < len(left) else ' '*lw
        r = right[i] if i < len(right) else ''
        res.append(l + r)
    return res

