    commits = commits_list()
    stashes = stashes_list()
    diff = current_diff().splitlines()
    if not diff:
        diff = ['No changed files']
    if opts.values.get('filter'):
        diff.insert(0, f"Filtering by path: {opts.values.get('filter')}")
    if message:
        diff.insert(0, message)
    top_h = 3
    files_h = max(7, rows//3)
    branches_h = max(6, rows//4)
    commits_h = max(6, rows//4)
    stash_h = 3
    left = []
    left += draw_box('[1]─Status', status, left_w, top_h)
    left += draw_box('[2]─Files - Worktrees - Submodules', file_lines, left_w, files_h, footer=f"{min(1,len(file_lines))} of {len(file_lines)}" if file_lines else None)
    left += draw_box('[3]─Local branches - Remotes - Tags', branches, left_w, branches_h, footer=f"1 of {len(branches)}" if branches else None)
    left += draw_box('[4]─Commits - Reflog', commits, left_w, commits_h, footer=f"1 of {len(commits)}" if commits else None)
    left += draw_box('[5]─Stash', stashes, left_w, max(3, rows-len(left)-2), footer=f"0 of {len(stashes)}")
    right_h = max(3, rows-4)
    right = draw_box('[0]─Unstaged changes' if files else '[0]─Diff', diff, right_w, right_h)
    cmd = draw_box('Command log', ['Compendium'], right_w, max(3, rows-right_h-1))
