        time.sleep(0.01)
        while select.select([sys.stdin], [], [], 0)[0]:
            ch += os.read(sys.stdin.fileno(),1)
            if len(ch)>8: break
    try: return ch.decode('utf-8','ignore')
    except Exception: return ''

